package org.sovereign.mesh.core

/**
 * Kotlin side of the Rust core. The Rust library is the only holder of keys
 * and plaintext history; this class forwards calls and never caches secrets.
 *
 * The real implementation will be generated by UniFFI from rust-core. Until
 * that is wired up, this stub keeps the UI runnable without any state.
 */
class CoreBridge {
    private val peers = mutableListOf<String>()

    fun peers(): List<String> = peers.toList()

    fun send(peer: String, text: String) {
        // Forwarded to rust-core; not persisted anywhere.
    }

    fun history(peer: String): List<String> = emptyList()

    fun forget(peer: String) {
        peers.remove(peer)
    }

    /** Called on activity stop. Mirrors Store::wipe_all in rust-core. */
    fun wipeAll() {
        peers.clear()
    }
}
